      return out+label(450,405,squeezed?'挤压：空气排出，不能同时画成已吸满液体':'松手：胶头恢复，外界大气压使液体进入')+text(650,180,'手动选择动作阶段',19,C.ink,'middle')+text(650,225,'吸液高度仅作示意',16,C.ink,'middle');
