    if(key==='bimetal-thermometer'){const bend=v.bendToward==='材料1'?80:v.bendToward==='材料2'?-80:0;return path(`M280 115q${bend} 120 0 240`,C.blue,15)+path(`M292 115q${bend} 120 0 240`,C.gold,12)+label(295,65,'双金属片（弯曲程度示意）')+panel(480,125,340,190,'自由热膨胀量比较')+text(500,175,'材料 1：'+F(N(v.lengthChange1)*1000,4)+' mm',17)+text(500,220,'材料 2：'+F(N(v.lengthChange2)*1000,4)+' mm',17)+text(500,268,'弯曲朝向：'+(v.bendToward||'等待计算'),17)+text(450,410,'自由伸长差只判断方向，不能直接当作实际弯曲曲率',15,C.ink,'middle');}
    if(key==='infrared-heating'){return path('M320 110L240 300H440Z',C.line,2,'#d3e8ee')+line(95,220,275,220,'#d6b965',7)+path('M275 220L398 220L680 250',C.red,3)+path('M275 220L402 235L680 305','#6b7db9',3)+rect(675,180,8,180,'#d4dfe5',C.line)+thermometer(730,165,150,v.temperature)+label(450,70,'在红光外侧比较温度变化')+text(450,405,'控制照射时间、传感器位置和环境条件',16,C.ink,'middle');}
    if(key==='iodine-sublimation'){const cooling=v.deposition===true,prog=clamp(N(v.progress,p.progress??.5),0,1);let out=beaker(170,175,230,160,.65)+path('M245 85h85v215q0 35-42 35t-43-35Z',C.line,3,'#e2ecf188');for(let i=0;i<Math.round(25*(cooling?1-prog:prog));i++)out+=circle(260+(i*31)%55,125+(i*29)%150,3,'#9875a4','none');return out+rect(265,300,45,22,'#584e65','#4d4854')+arrow(430,245,540,245,C.gold,3)+text(660,180,'密闭管内碘的状态变化',18,C.ink,'middle')+text(660,225,cooling?'冷却，观察固体重新出现':'温热水浴，观察紫色蒸气',15,C.ink,'middle')+text(660,270,'粒子图只表示观察阶段',15,C.ink,'middle')+text(450,399,'密闭演示；不能把任何可见烟雾都称为蒸气',15,C.ink,'middle');}
    if(key==='frost-can'){let out=rect(260,100,240,240,'#b6c6cf',C.line,8)+rect(285,140,80,60,'#e5f4fa','#88b9cf',4)+rect(385,210,80,60,'#d8eef6','#88b9cf',4);for(let i=0;i<(v.deposition===false?0:16);i++){const x=i%2===0?255:505,y=120+Math.floor(i/2)*29;out+=line(x-8,y,x+8,y,'#7aaac7',2)+line(x,y-8,x,y+8,'#7aaac7',2)+line(x-6,y-6,x+6,y+6,'#7aaac7',1);}return out+label(450,65,v.deposition===false?'当前条件下未出现霜':'低温罐外壁出现霜')+text(660,200,'空气中的水蒸气',18,C.ink,'middle')+text(660,245,'直接凝华为固态',19,C.ink,'middle')+text(450,399,'区分凝华结霜与液化结露',17,C.ink,'middle');}
    if(key==='alcohol-bag'){const cooling=v.condensing===true,prog=clamp(N(v.progress,p.progress??.5),0,1),bulge=cooling?50-prog*35:50+prog*45;return beaker(170,185,280,155,.7)+path(`M250 135Q${250-bulge} 290 310 315Q${375+bulge} 285 375 135Z`,C.line,3,'#e5eaf080')+rect(255,125,115,15,'#b0a28c','#806f57',3)+text(650,180,'密封软袋置于温水浴中',19,C.ink,'middle')+text(650,225,cooling?'冷却后袋体可能收缩':'温热后袋体可能鼓起',17,C.ink,'middle')+text(650,270,'酒精汽化与液化',17,C.ink,'middle')+label(450,70,'鼓缩为定性示意，没有气体体积刻度')+text(450,402,'密闭少量样品，远离明火',17,C.red,'middle');}
    if(key==='cold-water-reboil'){return path('M350 105H450V160Q535 180 535 265Q535 340 400 340Q265 340 265 265Q265 180 350 160Z',C.line,3,'#e3eef5')+path('M277 260Q400 285 523 260V280Q510 330 400 330Q290 330 277 280Z','#7da9c2',1,'#9dcce2')+rect(345,92,110,23,'#b49b71','#816d4f',3)+arrow(580,100,465,150,C.blue,3)+text(640,85,'冷水冷却瓶颈',17,C.ink,'middle')+label(665,225,'沸点 '+F(v.boilingPoint,1)+' ℃')+text(450,399,'蒸气遇冷液化，瓶内气压降低，水可能再次沸腾',15,C.ink,'middle');}
