    if(key==='rgb-mixture'){const colors=v.rgb||[N(p.red,255),N(p.green,255),N(p.blue,255)],light=(x,y,c)=>circle(x,y,88,c,'none').replace('<circle','<circle style="mix-blend-mode:screen"');return '<g style="isolation:isolate">'+rect(180,95,540,270,'#000','#58748a',3)+light(380,205,`rgb(${N(colors[0])},0,0)`)+light(510,205,`rgb(0,${N(colors[1])},0)`)+light(445,280,`rgb(0,0,${N(colors[2])})`)+'</g>'+label(450,55,'红、绿、蓝三原色光叠加')+text(450,405,'中央为三色光叠加；RGB 通道值不是实测光功率',15,C.ink,'middle');}
